import{z as s,x as i,o as r,c as d,q as A,j as o,D as e,d as E,s as B,S as n,b as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"评测与训练的协同","description":"","frontmatter":{"title":"评测与训练的协同","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ef-train-eval-synergy.md","filePath":"llm/ef-train-eval-synergy.md","lastUpdated":1791063341000}'),m={name:"llm/ef-train-eval-synergy.md"};function p(h,a,f,g,D,C){const t=i("Mermaid");return r(),d("div",null,[a[2]||(a[2]=A('<h1 id="评测与训练的协同" tabindex="-1">评测与训练的协同 <a class="header-anchor" href="#评测与训练的协同" aria-label="Permalink to &quot;评测与训练的协同&quot;">​</a></h1><div class="epigraph"><p>指南针可以给训练看，门禁不能；当评测变成训练目标的那一刻，它就开始失去当评测的资格。</p><footer>—— 据 Gao 等 2023（奖励过度优化）、Goodhart 定律口径与本课程评测课协议整理</footer></div><p><a href="/llm/ef-eval-portfolio">上一课</a>把仪器装配成组合。本课处理组合与训练的关系：评测发现的差距怎么喂回数据与奖励，训练的进度怎么看而不被吃掉。零件已就位：<a href="/llm/llm-judge-reward">裁判作奖励</a>写过法官进奖励的最低工程，<a href="/llm/in-training-eval">训练中评测</a>写过探针的隔离与频率，<a href="/llm/rlsys-eval-in-loop">评测在环</a>写过 RL 系统里的评测作业。本课补的是<strong>双列结构</strong>：哪些指标给训练当指南针、哪些锁进盲库当门禁，以及两列之间的信息通道该怎么开、怎么关。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>协同的失效有三种。<strong>同源循环</strong>：用同一张卷既指导训练又验收发布——模型对着它优化，分数涨而能力不涨，发布门禁形同虚设。<span class="marginnote">「同源循环」用考试打比方：模拟卷与高考卷本该分开出题。同一张卷既当练习题又当高考题，学生反复刷它——分数涨的是「背会了这张卷」，不是学会了知识。模型对着评测集优化是同一件事：门禁若与训练同源，它验收的就不再是能力。</span><strong>信号错位</strong>：拿门禁指标当训练损失，每个梯度步都在啃评测集；或反过来拿粗糙探针当发布依据，噪声直接进了决策。<strong>差距无处去</strong>：门禁失败了，报告写「未通过」就完，失败没有聚类、没有归因，下一轮训练只是换个种子重跑。三种失效同根：评测与训练之间没有受控的信息通道。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>双列表</strong>是骨架。指南针列：训练可见、高频、便宜——训练损失分桶、去污染探针、<a href="/llm/in-training-eval">训练中评测</a>的高频子集、RL 里的奖励曲线与 KL 散度；它们用来导航，明确声明「会被拟合」。<span class="marginnote">KL 散度可以粗糙理解为「新策略比旧策略跑偏了多远」的里程表。给 RLHF 定「KL 预算 10 纳特」等于说：允许模型离开起点这么远，走满即停。预算给小了安全但提升也小，给大了容易过度优化——所以它是要明确谈定的合同条款，不是随手填的默认值。</span>门禁列：训练不可见——盲库、公开新卷、人评抽审；只输出通过或失败，不进梯度。<strong>信息通道</strong>单向且经审批：门禁的失败样本脱敏、聚类后转成训练侧的数据需求（哪类失败、哪个子域、多少量），再走<a href="/llm/synthetic-eval-sets">数据采集或合成</a>补量；题面本身不过通道。<strong>奖励侧的审慎</strong>：法官或模型打分当奖励时，按<a href="/llm/llm-judge-reward">裁判作奖励</a>的最低工程执行，并预算好过度优化——Gao 等的缩放律显示，代理奖励单调上涨时，金标奖励先升后降，峰值之后的训练是在制造分数而非能力。</p>',7)),(r(),o(n,null,{default:e(()=>[B(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20GATE%5B%22%E7%9B%B2%E5%BA%93%E9%97%A8%E7%A6%81%EF%BC%9A%E9%80%9A%E8%BF%87%20%2F%20%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%E8%81%9A%E7%B1%BB%E4%B8%8E%E5%BD%92%E5%9B%A0%22%7C%20CH%5B%22%E5%AE%A1%E6%89%B9%E9%80%9A%E9%81%93%EF%BC%9A%E9%9C%80%E6%B1%82%E4%B8%8D%E5%B8%A6%E9%A2%98%E9%9D%A2%22%5D%0A%20%20CH%20--%3E%20DATA%5B%22%E6%95%B0%E6%8D%AE%E9%87%87%E9%9B%86%20%2F%20%E5%8F%97%E6%8E%A7%E5%90%88%E6%88%90%22%5D%0A%20%20DATA%20--%3E%20TRAIN%5B%22%E8%AE%AD%E7%BB%83%EF%BC%9A%E6%8C%87%E5%8D%97%E9%92%88%E5%88%97%E5%AF%BC%E8%88%AA%22%5D%0A%20%20TRAIN%20--%3E%20CKPT%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A%20%20CKPT%20--%3E%20GATE%0A%20%20TRAIN%20--%3E%7C%22%E5%8F%AF%E8%A7%81%22%7C%20NEEDLE%5B%22%E9%AB%98%E9%A2%91%E6%8E%A2%E9%92%88%E4%B8%8E%E5%A5%96%E5%8A%B1%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20PROBE2%5B%22%E4%BA%BA%E8%AF%84%E6%8A%BD%E5%AE%A1%22%5D%20--%3E%20GATE%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[E("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,[E("Goodhart 的机制版是：当代理指标 \\(\\tilde{R}\\) 成为优化目标，策略沿 \\(\\tilde{R}\\) 的梯度走出的分布离原先「\\(\\tilde{R}\\) 与真目标 \\(R\\) 相关」的分布越来越远，相关性衰减，最后 \\(\\tilde{R}\\) 涨 \\(R\\) 跌。Gao 等把它写成可预算的缩放律：给定 KL 预算，能算出金标奖励的峰值在哪，训练就该在哪附近收手——这给了「协同」一个定量抓手："),l("strong",null,"KL 预算是评测与训练之间的合同"),E("。门禁失败聚类为什么必须走归因而不是重跑：失败样本是分布信息，聚类给出「能力差、格式差还是判分器误伤」的分解，其中只有第一类该回流成训练数据，第二类该改后处理，第三类该修判定器——不分解的回流会把判定器的 bug 训进模型。")],-1)),(r(),o(n,null,{default:e(()=>[B(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E8%AE%AD%E7%BB%83%E6%B2%BF%E4%BB%A3%E7%90%86%E5%A5%96%E5%8A%B1%E6%A2%AF%E5%BA%A6%E8%B5%B0%22%5D%20--%3E%20M%5B%22%E4%BB%A3%E7%90%86%E5%A5%96%E5%8A%B1%20R~%20%E4%B8%80%E8%B7%AF%E4%B8%8A%E6%B6%A8%22%5D%0A%20%20M%20--%3E%20X%5B%22%E7%AD%96%E7%95%A5%E5%88%86%E5%B8%83%E8%B6%8A%E8%B5%B0%E8%B6%8A%E8%BF%9C%3Cbr%2F%3ER~%20%E4%B8%8E%E7%9C%9F%E7%9B%AE%E6%A0%87%20R%20%E7%9A%84%E7%9B%B8%E5%85%B3%E6%80%A7%E8%A1%B0%E5%87%8F%22%5D%0A%20%20X%20--%3E%20P%5B%22%E9%87%91%E6%A0%87%20R%20%E5%85%88%E5%8D%87%E5%90%8E%E8%B7%8C%3A%3Cbr%2F%3E%E5%B3%B0%E5%80%BC%E4%B9%8B%E5%90%8E%E5%8F%AA%E4%BA%A7%E5%88%86%E6%95%B0%E4%B8%8D%E4%BA%A7%E8%83%BD%E5%8A%9B%22%5D%0A%20%20P%20--%3E%20B%5B%22KL%20%E9%A2%84%E7%AE%97%20%3D%20%E5%9C%A8%E5%B3%B0%E5%80%BC%E5%89%8D%E6%94%B6%E6%89%8B%E7%9A%84%E5%90%88%E5%90%8C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">Gao 等 2023 的曲线值得贴在墙上：横轴是代理奖励优化量，代理奖励一路上扬，金标奖励先升后越过一个峰——「训练得最卖力的检查点」与「最好的检查点」不是同一个。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>协同有天花板：门禁只能拒绝，不能指路——它告诉你在哪失败，不告诉你怎么修；把门禁当课程表逐题训练，等于把最后一面干净的尺子也交出去。指南针太弱则训练失明：全部探针都藏起来，训练侧只剩损失，导航不回产品——隔离的粒度是「题面不可见、需求可流通」，不是全面断联。<span class="marginnote">初学者容易把「隔离」理解成全面断联：训练组什么都不许知道。实际隔离的粒度是「题面不可见、需求可流通」——门禁失败的聚类（哪类失败、缺什么数据）经审批照样喂给训练侧。全藏起来训练就失明了，导航不回产品；两头都留活口，只是通道必须单向、必须审批。</span>组织边界同样真实：盲库的读权限、通道的审批人、失败样本的脱敏责任人，都要有名有姓。最后，这套双列在 RLHF、RLVR 与持续学习里形态各异，但<a href="/llm/continual-eval-protocol">持续学习的评测协议</a>里「评测集不进训练存储」是同一条合同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>双列结构：指南针列训练可见可拟合，门禁列锁盲库只输出通过或失败。</li><li>信息通道单向经审批：失败聚类与数据需求过通道，题面不过。</li><li>KL 预算是评测与训练的合同；代理奖励的峰值靠缩放律预算，不靠感觉。</li><li>失败回流先归因：能力差改数据，格式差改后处理，判分误伤修判定器。</li><li>出处：Gao 等 2023（Scaling Laws for Reward Model Overoptimization）；Goodhart 定律口径；据本课程裁判作奖励、训练中评测与评测在环协议整理。</li></ul>',5))])}const T=s(m,[["render",p]]);export{u as __pageData,T as default};
